1	//! Property layer over the det-CBOR codec (blueprint/testing.md
2	//! "crates/core — KATs and property tests"): encode∘decode identity
3	//! including the unknown-field byte-stable round-trip, canonicality
4	//! rejection via the defect encoder in `common`, and the strict key
5	//! comparator's total-order laws. Case counts are bounded for CI speed;
6	//! failing seeds persist as regression vectors natively (persistence is
7	//! off under wasm, where the source tree may not be writable).
8	
9	mod common;
10	
11	use core::cmp::Ordering;
12	use std::collections::HashMap;
13	
14	use cipherbox_core::codec::{
15	    Map, Value, canonical_key_cmp, decode, decode_map_partial, encode, encode_map_partial,
16	};
17	use proptest::prelude::*;
18	
19	#[cfg(not(target_family = "wasm"))]
20	fn config() -> ProptestConfig {
21	    ProptestConfig::default()
22	}
23	
24	#[cfg(target_family = "wasm")]
25	fn config() -> ProptestConfig {
26	    ProptestConfig {
27	        // Bounded hard for the wasm32-wasip1 CI lane.
28	        cases: 16,
29	        // Writing regression files may not work under wasm.
30	        failure_persistence: None,
31	        ..ProptestConfig::default()
32	    }
33	}
34	
35	/// Bounded text including non-ASCII: `\PC` is any non-control char.
36	fn arb_text() -> impl Strategy<Value = String> {
37	    prop::string::string_regex("\\PC{0,12}").expect("valid regex")
38	}
39	
40	/// Map keys: shorter, still non-ASCII-capable.
41	fn arb_key() -> impl Strategy<Value = String> {
42	    prop::string::string_regex("\\PC{0,6}").expect("valid regex")
43	}
44	
45	/// The full profile data model, depth ≤ 4 and breadth ≤ 5 (CI-bounded).
46	/// Maps are built through `Map`'s inserting collector, which dedups and
47	/// canonically orders keys by construction.
48	fn arb_value() -> impl Strategy<Value = Value> {
49	    let leaf = prop_oneof![
50	        any::<u64>().prop_map(Value::Unsigned),
51	        any::<u64>().prop_map(Value::Negative),
52	        prop::collection::vec(any::<u8>(), 0..24).prop_map(Value::Bytes),
53	        arb_text().prop_map(Value::Text),
54	        any::<bool>().prop_map(Value::Bool),
55	        Just(Value::Null),
56	    ];
57	    leaf.prop_recursive(4, 24, 5, |inner| {
58	        prop_oneof![
59	            prop::collection::vec(inner.clone(), 0..=5).prop_map(Value::Array),
60	            prop::collection::vec((arb_key(), inner), 0..=5)
61	                .prop_map(|kvs| Value::Map(kvs.into_iter().collect())),
62	        ]
63	    })
64	}
65	
66	/// Map entries plus a per-key known/unknown flag (later duplicates win on
67	/// both sides, mirroring `Map::insert`), so `decode_map_partial` sees a
68	/// well-defined `is_known` and both sides of the split get exercised.
69	type FlaggedEntries = Vec<(String, Value, bool)>;
70	
71	fn arb_flagged_entries(min: usize) -> impl Strategy<Value = FlaggedEntries> {
72	    prop::collection::vec((arb_key(), arb_value(), any::<bool>()), min..=6)
73	}
74	
75	fn build_map_and_flags(entries: &FlaggedEntries) -> (Map, HashMap<String, bool>) {
76	    let mut map = Map::new();
77	    let mut flags = HashMap::new();
78	    for (k, v, known) in entries {
79	        map.insert(k.clone(), v.clone());
80	        flags.insert(k.clone(), *known);
81	    }
82	    (map, flags)
83	}
84	
85	proptest! {
86	    #![proptest_config(config())]
87	
88	    /// (a) decode is a left inverse of encode, and re-encoding the decode
89	    /// is byte-identical (canonical form is a fixed point).
90	    #[test]
91	    fn round_trip(v in arb_value()) {
92	        let bytes = encode(&v);
93	        let decoded = decode(&bytes).expect("own encoding must decode");
94	        prop_assert_eq!(&decoded, &v);
95	        prop_assert_eq!(encode(&decoded), bytes);
96	    }
97	
98	    /// (b) unknown-field tolerance is byte-stable: split a map into known
99	    /// and unknown by an arbitrary per-key assignment, re-emit unmodified,
100	    /// and the bytes are identical to the direct encoding.
101	    #[test]
102	    fn unknown_field_round_trip(entries in arb_flagged_entries(0)) {
103	        let (map, flags) = build_map_and_flags(&entries);
104	        let bytes = encode(&Value::Map(map.clone()));
105	        let (known, unknown) =
106	            decode_map_partial(&bytes, |k| flags.get(k).copied().unwrap_or(false))
107	                .expect("canonical map must decode");
108	        prop_assert_eq!(known.len() + unknown.len(), map.len());
109	        for (k, _) in known.entries() {
110	            prop_assert!(flags[k], "known side holds an unknown key {:?}", k);
111	        }
112	        for (k, _) in unknown.entries() {
113	            prop_assert!(!flags[k], "unknown side holds a known key {:?}", k);
114	        }
115	        let reencoded = encode_map_partial(&known, &unknown).expect("no collisions by construction");
116	        prop_assert_eq!(reencoded, bytes);
117	    }
118	
119	    /// (c) a rewrite through the partial codec re-encodes canonically:
120	    /// replacing one known field's value yields exactly the bytes of the
121	    /// fully-modified map encoded directly.
122	    #[test]
123	    fn rewrite_reencodes_canonically(
124	        entries in arb_flagged_entries(1),
125	        idx in any::<prop::sample::Index>(),
126	        replacement in arb_value(),
127	    ) {
128	        let target_key = entries[idx.index(entries.len())].0.clone();
129	        let (map, mut flags) = build_map_and_flags(&entries);
130	        // The rewritten key must be on the known side.
131	        flags.insert(target_key.clone(), true);
132	
133	        let bytes = encode(&Value::Map(map.clone()));
134	        let (mut known, unknown) =
135	            decode_map_partial(&bytes, |k| flags.get(k).copied().unwrap_or(false))
136	                .expect("canonical map must decode");
137	        known.insert(target_key.clone(), replacement.clone());
138	        let rewritten = encode_map_partial(&known, &unknown).expect("no collisions by construction");
139	
140	        let mut full = map;
141	        full.insert(target_key, replacement);
142	        prop_assert_eq!(rewritten, encode(&Value::Map(full)));
143	    }
144	
145	    /// (d) every single-defect mutation of a canonical encoding rejects
146	    /// with exactly the named check, whatever the payload.
147	    #[test]
148	    fn canonicality_rejection(
149	        v in arb_value(),
150	        v2 in arb_value(),
151	        k1 in arb_key(),
152	        k2 in arb_key(),
153	    ) {
154	        prop_assume!(k1 != k2);
155	        let (lo, hi) = match canonical_key_cmp(&k1, &k2) {
156	            Ordering::Less => (&k1, &k2),
157	            _ => (&k2, &k1),
158	        };
159	        let cases = [
160	            common::widen_head(&v),
161	            common::widen_length(&v),
162	            common::indefinite_array(&v),
163	            common::swap_map_keys(lo, hi, &v, &v2),
164	            common::duplicate_key(&k1, &v, &v2),
165	            common::wrap_tag(&v),
166	            common::inject_float(&v),
167	            common::trailing_junk(&v),
168	            common::truncate(&v),
169	        ];
170	        for (bytes, expected) in cases {
171	            match decode(&bytes) {
172	                Ok(value) => prop_assert!(
173	                    false,
174	                    "defect {} was accepted as {} (bytes {:02x?})",
175	                    expected, value, bytes
176	                ),
177	                Err(err) => prop_assert_eq!(
178	                    err.check(),
179	                    expected,
180	                    "wrong check for defect bytes {:02x?}",
181	                    bytes
182	                ),
183	            }
184	        }
185	    }
186	
187	    /// (e) `canonical_key_cmp` is a total order that agrees with bytewise
188	    /// comparison of the encoded keys — the strict-comparator groundwork
189	    /// (idempotence, antisymmetry, transitivity, platform stability).
190	    #[test]
191	    fn map_key_order_is_total_and_platform_stable(
192	        a in arb_key(),
193	        b in arb_key(),
194	        c in arb_key(),
195	    ) {
196	        // Idempotence / reflexivity.
197	        prop_assert_eq!(canonical_key_cmp(&a, &a), Ordering::Equal);
198	        // Antisymmetry.
199	        prop_assert_eq!(canonical_key_cmp(&a, &b), canonical_key_cmp(&b, &a).reverse());
200	        // Equality is identity: no two distinct keys compare Equal.
201	        if canonical_key_cmp(&a, &b) == Ordering::Equal {
202	            prop_assert_eq!(&a, &b);
203	        }
204	        // Transitivity of ≤.
205	        if canonical_key_cmp(&a, &b) != Ordering::Greater
206	            && canonical_key_cmp(&b, &c) != Ordering::Greater
207	        {
208	            prop_assert!(canonical_key_cmp(&a, &c) != Ordering::Greater);
209	        }
210	        // Platform stability: the (len, bytes) shortcut equals RFC 8949's
211	        // bytewise-lexicographic order over the full encoded key items.
212	        prop_assert_eq!(
213	            canonical_key_cmp(&a, &b),
214	            encode(&Value::Text(a.clone())).cmp(&encode(&Value::Text(b.clone())))
215	        );
216	    }
217	}
